type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E };

function ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

function err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

function isOk<T, E>(r: Result<T, E>): r is { ok: true; value: T } {
  return r.ok;
}

function parseIntSafe(s: string): Result<number, string> {
  const n = Number(s);
  return Number.isNaN(n) ? err('not a number') : ok(n);
}

const r = parseIntSafe('42');
if (isOk(r)) {
  console.log(r.value); // number, narrowed
} else {
  console.error(r.error); // string
}

function isString(value: unknown): value is string {
  return typeof value === 'string';
}

function printUpper(value: unknown): void {
  if (isString(value)) {
    console.log(value.toUpperCase()); // value: string here
  } else {
    console.log('not a string');
  }
}

async function fetchJson<T>(
  url: string,
  init?: RequestInit
): Promise<T> {
  const res = await fetch(url, init);
  if (!res.ok) {
    throw new Error(`HTTP ${res.status} for ${url}`);
  }
  const data: unknown = await res.json();
  return data as T; // boundary assertion; validate for real safety
}

interface User {
  id: number;
  name: string;
}

async function loadUser(id: number): Promise<User> {
  return fetchJson<User>(`/api/users/${id}`);
}

